import{z as p,x as B,o as E,c as A,q as t,j as o,D as n,d as r,s as l,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const k=JSON.parse('{"title":"Keynes《通论》问题设定","description":"","frontmatter":{"title":"Keynes《通论》问题设定","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/keynes-general-theory.md","filePath":"econ/keynes-general-theory.md","lastUpdated":1791413859000}'),d={name:"econ/keynes-general-theory.md"};function m(h,e,c,D,u,y){const s=B("Mermaid");return E(),A("div",null,[e[2]||(e[2]=t('<h1 id="keynes《通论》问题设定" tabindex="-1">Keynes《通论》问题设定 <a class="header-anchor" href="#keynes《通论》问题设定" aria-label="Permalink to &quot;Keynes《通论》问题设定&quot;">​</a></h1><div class="epigraph"><p>古典理论假定充分就业是常态；本书要说明：有效需求不足时，失业可以与均衡并存。</p><footer>—— Keynes, The General Theory of Employment, Interest and Money, 1936</footer></div><p><a href="/econ/ms-1983-paper">上一课</a>（Myerson–Satterthwaite 原文）。附录对照。本篇不插入主干课序，也不把 Hicks（1937）的 IS–LM 写成凯恩斯本人。<a href="/econ/is-lm">IS–LM 作为会计</a>、<a href="/econ/natural-unemployment">失业与自然率</a>已从后起的宏观语言取用。这里对照 <strong>1936 年原书的问题</strong>：劳动市场为何可以停在非充分就业，利率又为何不能单独把储蓄与投资拧平。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>古典（Keynes 所批评的 Marshall–Pigou 传统）让实际工资出清劳动，让利率出清储蓄与投资。失业是摩擦性或自愿的；节俭会降低利率、提高投资。1930 年代的经验使这条链不可信。《通论》的缺口不是再画一条劳动供给，而是：产出由<strong>有效需求</strong>决定，就业是产出的派生；利率在货币市场上由流动性偏好决定，不保证投资自动吸收充分就业下的储蓄。</p><p>原书因此把「一般」对着古典的「特殊」：充分就业只是有效需求刚好够到的特例。附录对照的是这一定位，不是逐章复述乘数算术，也不是后来的粘性价格微观基础。</p><p><span class="marginnote">有效需求：企业家预期能卖出的、与就业决策一致的总需求点。流动性偏好：利率使公众愿意持有现有货币存量。资本边际效率：预期收益折现与资产供给价格的关系，不是物理的资本边际产品。</span></p><p><span class="marginnote">直觉类比（节俭悖论）：一个人少花钱多存钱，他的存款确实变多；全社会同时这么做，消费萎缩、企业卖不掉货、产出与收入收缩，最后大家的总储蓄反而没多起来。个体理性加总成集体困境，这正是「产出由有效需求决定」的另一面。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三块积木，原书用散文而不是联立方程组。第一，消费倾向：收入增加时消费增加得更少，留下的缺口必须由投资填。第二，投资由资本边际效率与利率比较决定；MEC 随资本存量与预期摇摆。第三，货币需求含交易与投机动机，利率是放弃流动性的价格。三块联在一起：利率不必把 S 与 I 带到充分就业那一点；产出会下降到使储蓄等于投资。</p>',10)),(E(),o(i,null,{default:n(()=>[l(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ED%5B%22%E6%9C%89%E6%95%88%E9%9C%80%E6%B1%82%22%5D%20--%3E%20Y%5B%22%E4%BA%A7%E5%87%BA%E4%B8%8E%E5%B0%B1%E4%B8%9A%22%5D%0A%20%20MEC%5B%22%E8%B5%84%E6%9C%AC%E8%BE%B9%E9%99%85%E6%95%88%E7%8E%87%22%5D%20--%3E%20I%5B%22%E6%8A%95%E8%B5%84%22%5D%0A%20%20LP%5B%22%E6%B5%81%E5%8A%A8%E6%80%A7%E5%81%8F%E5%A5%BD%22%5D%20--%3E%20R%5B%22%E5%88%A9%E7%8E%87%22%5D%0A%20%20R%20--%3E%20I%0A%20%20I%20--%3E%20ED%0A%20%20C%5B%22%E6%B6%88%E8%B4%B9%E5%80%BE%E5%90%91%22%5D%20--%3E%20ED%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,"Hicks 1937 把后两块收成 IS 与 LM 两条曲线，便于比较静态。那是对照读物，不是 1936 的本文。主干 IS–LM 课已经声明自己是会计；本附录禁止倒灌，说「凯恩斯证明了 LM」。",-1)),e[4]||(e[4]=a("p",null,[a("span",{class:"marginnote"},"数字实例（乘数）：消费倾向 0.6 时，1 元新增投资先变成 1 元收入，其中 0.6 元又被消费掉、变成别人的收入……加总为 \\(1/(1-0.6)=2.5\\) 元。储蓄倾向越高，收入漏出的口子越大，乘数越小——「消费增加得比收入少」这句话的全部算术就在这里。")],-1)),e[5]||(e[5]=a("h2",{id:"机制",tabindex:"-1"},[r("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[6]||(e[6]=a("p",null,"机制是预期与存量约束，不是单纯的名义工资刚性——虽然工资章确实讨论货币工资难以下调。即使工资更有弹性，需求收缩仍可通过价格、债务负担与流动性偏好把就业压住。利率的功能被改写：它不是节俭的奖赏，是货币与债券之间的选择。储蓄增加首先减少有效需求，而不是自动变成投资。",-1)),(E(),o(i,null,{default:n(()=>[l(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUP%5B%22%E5%82%A8%E8%93%84%E6%84%8F%E6%84%BF%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20CL%5B%22%E5%8F%A4%E5%85%B8%E9%93%BE%E6%9D%A1%3A%20%E5%88%A9%E7%8E%87%E4%B8%8B%E9%99%8D%22%5D%0A%20%20CL%20--%3E%20IUP%5B%22%E6%8A%95%E8%B5%84%E8%A2%AB%E4%BD%8E%E5%88%A9%E7%8E%87%E6%8B%89%E8%B5%B7%22%5D%0A%20%20IUP%20--%3E%20FULL%5B%22%E4%BB%8D%E5%9B%9E%E5%85%85%E5%88%86%E5%B0%B1%E4%B8%9A%22%5D%0A%20%20SUP%20--%3E%20KEY%5B%22%E5%87%AF%E6%81%A9%E6%96%AF%E9%93%BE%E6%9D%A1%3A%20%E6%9C%89%E6%95%88%E9%9C%80%E6%B1%82%E5%85%88%E5%87%8F%22%5D%0A%20%20KEY%20--%3E%20YDOWN%5B%22%E4%BA%A7%E5%87%BA%E4%B8%8E%E5%B0%B1%E4%B8%9A%E6%94%B6%E7%BC%A9%22%5D%0A%20%20YDOWN%20--%3E%20SADJ%5B%22%E5%82%A8%E8%93%84%E8%A2%AB%E5%8A%A8%E9%99%8D%E5%9B%9E%E4%B8%8E%E6%8A%95%E8%B5%84%E7%9B%B8%E7%AD%89%22%5D%0A"})]),fallback:n(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=t('<p><span class="marginnote">常见误区：以为《通论》的关键只是「工资太刚」。原文的机制更根本：即使货币工资有弹性，需求收缩仍能通过债务负担与流动性偏好压住就业；利率也不再是「节俭的奖赏」，而是放弃流动性的报酬。把书读成「粘性工资故事」会漏掉这一层。</span></p><p>这与后来<a href="/econ/consumption-euler">跨期欧拉</a>的对照：欧拉把消费写成利率的平滑；《通论》的消费倾向几乎不随利率动，利率走投资与货币。两种机制在主干里分属不同课，附录不把 1936 改写成欧拉。</p><h3 id="问题设定-不是-nk-三方程" tabindex="-1">问题设定，不是 NK 三方程 <a class="header-anchor" href="#问题设定-不是-nk-三方程" aria-label="Permalink to &quot;问题设定，不是 NK 三方程&quot;">​</a></h3><p>主干用 IS–LM 当会计、用欧拉与粘性当跨期。附录只对照 Keynes 认为古典留下的缺口：产量可以由有效需求停在低于充分就业处；利息是流动性的价格。动物精神、长期预期的崩溃，在原文是散文，在后来的 NK 里被再编码。不要用 1936 年为某项当代政策背书，也不要用微观基础「否证」一本问题设定的书。</p><p><span class="marginnote">Keynes, <em>The General Theory of Employment, Interest and Money</em>, Macmillan, 1936。希克斯 1937 年 <em>Econometrica</em> 是翻译，不是原文。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要用《通论》当 IS–LM 习题集，也不要用它当「财政永远乘数大于一」的许可证——乘数依赖于未充分就业与利率如何反应，后一截在流动性陷阱讨论里才尖锐。一般均衡对照：Debreu 的市场是出清的；Keynes 的问题恰恰是劳动市场可以在非出清处停住，对象已经换了。</p><p>下一篇附录对照 Friedman 如何把货币数量写成稳定的需求函数，而不是《通论》的投机陷阱。</p><p>有效需求决定产量，不是要素市场出清决定产量。储蓄随收入被动适应，而不是事先决定投资。</p><p>利息是放弃流动性的报酬，可以钉在阻碍充分就业投资的水平。流动性陷阱是这一逻辑的极端。</p><p>希克斯 1937 年的 IS–LM 是翻译。主干已声明那是会计。附录禁止说「凯恩斯证明了 LM」。</p><p>《通论》不是银行挤兑模型，也不是 SDF。不要把一切宏观还原成 Keynes。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照《通论》：有效需求决定就业；利率由流动性偏好决定。</li><li>充分就业是特例，不是古典假定的常态。</li><li>IS–LM 是 Hicks 的翻译，不是原文方程。</li><li>出处：Keynes, <em>The General Theory</em>, 1936；对照 Hicks, <em>Econometrica</em> 1937。</li></ul>',14))])}const S=p(d,[["render",m]]);export{k as __pageData,S as default};
